import{_ as e,o,c as n,ah as s}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"Sound Concept: Episode 1 – The Whispers of Gold","description":"","frontmatter":{},"headers":[],"relativePath":"en/hoerbuch/sound-konzept-episode-1.md","filePath":"en/hoerbuch/sound-konzept-episode-1.md"}'),r={name:"en/hoerbuch/sound-konzept-episode-1.md"};function i(a,t,l,d,h,u){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="sound-concept-episode-1-–-the-whispers-of-gold" tabindex="-1">Sound Concept: Episode 1 – The Whispers of Gold <a class="header-anchor" href="#sound-concept-episode-1-–-the-whispers-of-gold" aria-label="Permalink to &quot;Sound Concept: Episode 1 – The Whispers of Gold&quot;">​</a></h1><p>This document serves as an acoustic directorial instruction for the production of the first audiobook episode. It defines the sound effects (SFX), the musical accompaniment, and the atmospheric layers.</p><hr><h2 id="_1-atmo-layers-base-mood" tabindex="-1">1. Atmo Layers (Base Mood) <a class="header-anchor" href="#_1-atmo-layers-base-mood" aria-label="Permalink to &quot;1. Atmo Layers (Base Mood)&quot;">​</a></h2><p>These sounds run subtly in the background of the respective acts:</p><ul><li><strong>Act 1 (Heidi):</strong> &quot;Rich Lake&quot; – Gentle, rhythmic splashing of water against a ship&#39;s hull, distant calls of seagulls, the soft hum of an air conditioner (high-end luxury).</li><li><strong>Act 2 (Helmut 1936):</strong> &quot;Industrial Grey&quot; – A deep, mechanical drone, the distant roar of factory chimneys, the reverb of a large, nearly empty room.</li><li><strong>Act 3 (August W. 2026):</strong> &quot;Fluorescent Stress&quot; – The nervous hum of neon tubes, distant murmurs in a courtroom hallway, the rubbing of fabric on leather (unrest on the defendant&#39;s bench).</li></ul><hr><h2 id="_2-specific-sfx-cues-timestamp-based" tabindex="-1">2. Specific SFX Cues (Timestamp-based) <a class="header-anchor" href="#_2-specific-sfx-cues-timestamp-based" aria-label="Permalink to &quot;2. Specific SFX Cues (Timestamp-based)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Segment</th><th style="text-align:left;">Action / Dialogue Line</th><th style="text-align:left;">Sound Effect (SFX)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Intro</strong></td><td style="text-align:left;">&quot;Money never sleeps...&quot;</td><td style="text-align:left;"><strong>Ticking of a Patek Philippe</strong>, stopping abruptly. Then: <strong>Shower of gold coins</strong> on a marble floor.</td></tr><tr><td style="text-align:left;"><strong>Act 1</strong></td><td style="text-align:left;">&quot;Sound of a pearl necklace...&quot;</td><td style="text-align:left;"><strong>Clicking of pearl on pearl</strong> (extremely close-miked), followed by the <strong>rustle of heavy silk</strong>.</td></tr><tr><td style="text-align:left;"><strong>Act 1</strong></td><td style="text-align:left;">&quot;Rain of Gold&quot; (Grok)</td><td style="text-align:left;"><strong>Synthetic thunder roll</strong>, transforming into the <strong>patter of coins</strong> (like rain).</td></tr><tr><td style="text-align:left;"><strong>Act 2</strong></td><td style="text-align:left;">&quot;Duisburg, April 23, 1936&quot;</td><td style="text-align:left;"><strong>Hard clicking of typewriter keys</strong>, a mechanical <strong>carriage return</strong>.</td></tr><tr><td style="text-align:left;"><strong>Act 2</strong></td><td style="text-align:left;">&quot;While the ink dries...&quot;</td><td style="text-align:left;"><strong>Sound of a nib on paper</strong>, followed by the <strong>slamming of a heavy vault</strong>.</td></tr><tr><td style="text-align:left;"><strong>Act 3</strong></td><td style="text-align:left;">&quot;WhatsApp notification sounds&quot;</td><td style="text-align:left;"><strong>Serial popping</strong> of iOS notifications (overlapping, creating a feeling of overwhelm).</td></tr><tr><td style="text-align:left;"><strong>Act 3</strong></td><td style="text-align:left;">&quot;Judge&#39;s gavel strike&quot;</td><td style="text-align:left;">A <strong>dull, echoing strike</strong>, digitally distorted and transitioning into the outro beat.</td></tr></tbody></table><hr><h2 id="_3-musical-guidelines" tabindex="-1">3. Musical Guidelines <a class="header-anchor" href="#_3-musical-guidelines" aria-label="Permalink to &quot;3. Musical Guidelines&quot;">​</a></h2><ul><li><strong>Theme &quot;The Gold&quot;:</strong> A solitary cello, tuned very low, plays an elegant but melancholic melody in a minor key. It symbolizes the burden of wealth.</li><li><strong>Theme &quot;The AI&quot;:</strong> Short, high-frequency glitch sounds and minimal sine tones marking the transition between Grok and Gemini.</li><li><strong>Theme &quot;Aryanization&quot;:</strong> A sluggish, almost military rhythm created by the rhythmic closing of archive drawers.</li></ul><hr><p><em>Concept created by Gemini CLI for Volti Sodala. February 2026.</em></p>',14)])])}const f=e(r,[["render",i]]);export{c as __pageData,f as default};
